        "translation": "„Și Dumnezeu a făcut sălbăticiunile pământului după soiul lor și dobitoacele după soiul lor și toate târâtoarele pământului după soiul lor. Și Dumnezeu a văzut că este bine.” — traducerea rabinului Rosen.",
        "note": ""
